function amortizedMonthly(buildCost, months) {
  return buildCost / months;
}

function usageInMonth(startGb, growthPerMonth, month) {
  return startGb + growthPerMonth * (month - 1);
}

function totalCost(monthlyCosts) {
  let total = 0;
  for (const cost of monthlyCosts) total += cost;
  return total;
}

function savings(costsA, costsB) {
  const sum = (xs) => xs.reduce((a, b) => a + b, 0);
  return sum(costsA) - sum(costsB);
}

