function yearWinner(fixedA, perUnitA, fixedB, perUnitB, startUsage, growth) {
  let totalA = 0;
  let totalB = 0;
  for (let m = 1; m <= 12; m++) {
    const usage = startUsage + growth * (m - 1);
    totalA += fixedA + perUnitA * usage;
    totalB += fixedB + perUnitB * usage;
  }
  if (totalA < totalB) return "A";
  if (totalB < totalA) return "B";
  return "tie";
}

