function firstMonthBWins(fixedA, perUnitA, fixedB, perUnitB, startUsage, growth) {
  for (let m = 1; m <= 12; m++) {
    const usage = startUsage + growth * (m - 1);
    if (fixedB + perUnitB * usage < fixedA + perUnitA * usage) return m;
  }
  return 0;
}
